package app

import (
	cf "library/internal/pkg/config"
	pb "library/internal/pkg/genproto"
	"library/internal/pkg/postgres"
	"library/internal/storage/repo"
	"log"
	"net"

	"google.golang.org/grpc"
)

func Run(cf *cf.Config) {
	pgm, err := postgres.New(cf)
	if err != nil {
		log.Fatal("Failed to connect to database:", err)
	}
	defer pgm.Close()

	UR := repo.NewUserRepo(pgm.DB)

	lis, err := net.Listen("tcp", cf.GRPCPort)
	if err != nil {
		log.Fatal("Failed to listen:", err)
	}

	server := grpc.NewServer()
	pb.RegisterUserServiceServer(server, UR)

	log.Println("Server is running on port:", cf.GRPCPort)
	if err := server.Serve(lis); err != nil {
		log.Fatal("Failed to serve:", err)
	}
	defer server.GracefulStop()
	defer lis.Close()
}

