package config

import (
	"fmt"
	"os"

	"github.com/joho/godotenv"
	"github.com/spf13/cast"
)

type Config struct {
	GRPCPort string

	PostgresHost     string
	PostgresPort     int
	PostgresUser     string
	PostgresPassword string
	PostgresDatabase string
}

func Load() Config {
	if err := godotenv.Load(); err != nil {
		fmt.Println("No .env file found")
	}

	config := Config{}

	config.GRPCPort = cast.ToString(get("GRPC_PORT", ":"))

	config.PostgresHost = cast.ToString(get("POSTGRES_HOST", "localhost"))
	config.PostgresPort = cast.ToInt(get("POSTGRES_PORT", 542))
	config.PostgresUser = cast.ToString(get("POSTGRES_USER", "postgres"))
	config.PostgresPassword = cast.ToString(get("POSTGRES_PASSWORD", "1234"))
	config.PostgresDatabase = cast.ToString(get("POSTGRES_DATABASE", "proycts"))

	return config
}

func get(key string, defaultValue interface{}) interface{} {
	val, exists := os.LookupEnv(key)

	if exists {
		return val
	}

	return defaultValue
}

