package repo

import (
	"context"
	"database/sql"
	pb "library/internal/pkg/genproto"
	"time"
)

type UserRepo struct {
	db *sql.DB
	pb.UnimplementedUserServiceServer
}

func NewUserRepo(db *sql.DB) *UserRepo {
	return &UserRepo{db: db}
}

func (r *UserRepo) CreateUser(ctx context.Context, req *pb.UserCreateReq) (*pb.Void, error) {
	query := `
		INSERT INTO users (full_name, group_name, email, phone, role, created_at) 
		VALUES ($1, $2, $3, $4, $5, $6)`
	_, err := r.db.Exec(
		query,
		req.FullName,
		req.GroupName,
		req.Email,
		req.Phone,
		req.Role,
		time.Now(),
	)

	if err != nil {
		return nil, err
	}
	return nil, nil
}

func (r *UserRepo) GetUser(ctx context.Context, req *pb.ByID) (*pb.UserGetRes, error) {
	query := "SELECT * FROM users WHERE id = $1"
	var user pb.UserGetRes
	err := r.db.QueryRow(query, req.Id).Scan(
		&user.Id,
		&user.FullName,
		&user.GroupName,
		&user.Email,
		&user.Phone,
		&user.Role,
		&user.CreatedAt,
		&user.UpdatedAt,
	)
	if err != nil {
		return nil, err
	}
	return &user, nil
}

func (r *UserRepo) UpdateUser(ctx context.Context, req *pb.UserUpdateReq) (*pb.Void, error) {
	query := `
		UPDATE users SET full_name = $1, group_name = $2, email = $3, phone = $4, role =
		$5, updated_at = $6 WHERE id = $7`
	_, err := r.db.Exec(
		query,
		req.Body.FullName,
		req.Body.GroupName,
		req.Body.Email,
		req.Body.Phone,
		req.Body.Role,
		time.Now(),
		req.Id,
	)
	if err != nil {
		return nil, err
	}
	return nil, nil

}

func (r *UserRepo) DeleteUser(ctx context.Context, req *pb.ByID) (*pb.Void, error) {
	query := "DELETE FROM users WHERE id = $1"
	_, err := r.db.Exec(query, req.Id)
	if err != nil {
		return nil, err
	}
	return nil, nil
}

func (r *UserRepo) GetAllUsers(ctx context.Context, req *pb.UsersGetAllReq) (*pb.UsersGetAllRes, error) {
	offset := (req.Offset - 1) * req.Limit
	query := `SELECT id, full_name, group_name, email, phone, role, created_at, updated_at FROM users LIMIT $1 OFFSET $2`
	rows, err := r.db.QueryContext(ctx, query, req.Limit, offset)
	if err != nil {
		return nil, err
	}
	defer rows.Close()

	var users []*pb.UserGetRes
	for rows.Next() {
		var user pb.UserGetRes
		err := rows.Scan(
			&user.Id,
			&user.FullName,
			&user.GroupName,
			&user.Email,
			&user.Phone,
			&user.Role,
			&user.CreatedAt,
			&user.UpdatedAt,
		)
		if err != nil {
			return nil, err
		}
		users = append(users, &user)
	}

	if err = rows.Err(); err != nil {
		return nil, err
	}

	totalCountQuery := `SELECT count(id) FROM users`
	var totalCount int64
	if err = r.db.QueryRowContext(ctx, totalCountQuery).Scan(&totalCount); err != nil {
		return nil, err
	}

	return &pb.UsersGetAllRes{
		Users: users,
		Total: totalCount,
	}, nil
}

