func (r *UserRepo) GetAllUsers(ctx context.Context, req *pb.UsersGetAllReq) (*pb.UsersGetAllRes, error) {
	// base query
	query := `
		SELECT id, full_name, group_name, email, phone, role, created_at, updated_at
