	// search (matches full_name, email, or phone)
	if req.Search != "" {
		query += fmt.Sprintf(" AND (full_name ILIKE $%d OR email ILIKE $%d OR phone ILIKE $%d)", argCount, argCount+1, argCount+2)
		args = append(args, "%"+req.Search+"%", "%"+req.Search+"%", "%"+req.Search+"%")
		argCount += 3
	}

	// filter by group name
	if req.GroupName != "" {
		query += fmt.Sprintf(" AND group_name = $%d", argCount)
		args = append(args, req.GroupName)
		argCount++
	}

	// filter by role
	if req.Role != "" {
		query += fmt.Sprintf(" AND role = $%d", argCount)
		args = append(args, req.Role)
		argCount++
	}

	// pagination
	query += fmt.Sprintf(" LIMIT $%d OFFSET $%d", argCount, argCount+1)
	args = append(args, req.Limit, (req.Offset-1)*req.Limit)

	rows, err := r.db.QueryContext(ctx, query, args...)
	if err != nil {
		return nil, err
	}
	defer rows.Close()

	// scan results
	var users []*pb.UserGetRes
	for rows.Next() {
		var user pb.UserGetRes
		if err := rows.Scan(
			&user.Id,
			&user.FullName,
			&user.GroupName,
			&user.Email,
			&user.Phone,
			&user.Role,
			&user.CreatedAt,
			&user.UpdatedAt,
		); err != nil {
			return nil, err
		}
		users = append(users, &user)
	}
	if err = rows.Err(); err != nil {
		return nil, err
	}

	// count query (for pagination metadata)
	countQuery := "SELECT count(id) FROM users WHERE 1=1"
	var countArgs []interface{}
	argCount = 1

	if req.Search != "" {
		countQuery += fmt.Sprintf(" AND (full_name ILIKE $%d OR email ILIKE $%d OR phone ILIKE $%d)", argCount, argCount+1, argCount+2)
		countArgs = append(countArgs, "%"+req.Search+"%", "%"+req.Search+"%", "%"+req.Search+"%")
		argCount += 3
	}
	if req.GroupName != "" {
		countQuery += fmt.Sprintf(" AND group_name = $%d", argCount)
		countArgs = append(countArgs, req.GroupName)
		argCount++
	}
	if req.Role != "" {
		countQuery += fmt.Sprintf(" AND role = $%d", argCount)
		countArgs = append(countArgs, req.Role)
		argCount++
	}

	var totalCount int64
	if err = r.db.QueryRowContext(ctx, countQuery, countArgs...).Scan(&totalCount); err != nil {
		return nil, err
	}

	return &pb.UsersGetAllRes{
		Users: users,
		Total: totalCount,
	}, nil
}
```

---

### 🔑 Key Points
- `WHERE 1=1` makes it easy to append conditions.  
- `ILIKE` is used for **case-insensitive search**.  
- For search, we used **3 placeholders at once** (`full_name`, `email`, `phone`).  
- Pagination still works with `LIMIT` and `OFFSET`.  
- Count query reuses the same filters (important for `Total`).  

