	var countArgs []interface{}
	argCount = 1

	if req.Search != "" {
		countQuery += fmt.Sprintf(" AND (name ILIKE $%d OR description ILIKE $%d)", argCount, argCount+1)
		countArgs = append(countArgs, "%"+req.Search+"%", "%"+req.Search+"%")
