func (r *AuthorRepo) Create(ctx context.Context, req *pb.AuthorCreateReq) error {
	query := `
		INSERT INTO authors (name, birth_date, biography)
		VALUES ($1, $2, $3)`
	_, err := r.db.Exec(ctx, query, req.Name, req.BirthDate, req.Biography)
	return err
}

// Get author by ID
func (r *AuthorRepo) Get(ctx context.Context, id string) (*pb.AuthorGetRes, error) {
	var res pb.AuthorGetRes

	query := `
		SELECT id, name, birth_date, biography
		FROM authors
		WHERE id = $1`
	err := r.db.QueryRow(ctx, query, id).Scan(
		&res.Id, &res.Name, &res.BirthDate, &res.Biography,
	)
	if err != nil {
		return nil, err
	}
	return &res, nil
}

// Update author
func (r *AuthorRepo) Update(ctx context.Context, req *pb.AuthorUpdateReq) error {
	query := `
		UPDATE authors
		SET name = $1,
		    birth_date = $2,
		    biography = $3
		WHERE id = $4`
	_, err := r.db.Exec(ctx, query, req.Body.Name, req.Body.BirthDate, req.Body.Biography, req.Id)
	return err
}

// Delete author
func (r *AuthorRepo) Delete(ctx context.Context, id string) error {
	query := `DELETE FROM authors WHERE id = $1`
	_, err := r.db.Exec(ctx, query, id)
	return err
}

// Get all authors
func (r *AuthorRepo) GetAll(ctx context.Context, req *pb.AuthorsGetAllReq) (*pb.GetAllAuthorsRes, error) {
	res := &pb.GetAllAuthorsRes{Authors: []*pb.AuthorGetRes{}}

	query := `
		SELECT id, name, birth_date, biography
		FROM authors
		WHERE name ILIKE '%' || $1 || '%'
		ORDER BY name
		LIMIT $2 OFFSET $3`

	rows, err := r.db.Query(ctx, query, req.Search, req.Limit, req.Offset)
	if err != nil {
		return nil, err
	}
	defer rows.Close()

	for rows.Next() {
		author := &pb.AuthorGetRes{}
		err := rows.Scan(&author.Id, &author.Name, &author.BirthDate, &author.Biography)
		if err != nil {
			return nil, err
		}
		res.Authors = append(res.Authors, author)
	}

	// count total
	countQuery := `SELECT COUNT(*) FROM authors WHERE name ILIKE '%' || $1 || '%'`
	err = r.db.QueryRow(ctx, countQuery, req.Search).Scan(&res.TotalCount)
	if err != nil {
		return nil, err
	}

	return res, nil
}
