Right now your query is only checking the **first** category (`req.CategoryIds[0]`) and same problem will happen once we add authors.  
We need to support **multiple values** (show books that belong to *any* of the requested categories/authors).  

The correct way in Postgres is to use `= ANY($X)` or `IN (SELECT UNNEST(...))`.  

Here’s a rewritten `GetAllBooks` with **multi-category** and **multi-author** filtering:  

```go
func (r *BookRepo) GetAllBooks(ctx context.Context, req *pb.BooksGetAllReq) (*pb.BooksGetAllRes, error) {
	query := `
		SELECT id, title, cover_image_url, file_url, location, is_reference_only, description,
		       isbn, published_date, publisher_id, language, page_count, total_copies, available_copies
		FROM books
		WHERE 1=1
	`
	var args []interface{}
	argCount := 1

	// filters
	if req.Location != "" {
		query += fmt.Sprintf(" AND location ILIKE $%d", argCount)
		args = append(args, "%"+req.Location+"%")
		argCount++
	}

	// categories filter (ANY match)
	if len(req.CategoryIds) > 0 {
		query += fmt.Sprintf(`
			AND EXISTS (
				SELECT 1 FROM book_categories bc
				WHERE bc.book_id = books.id
				  AND bc.category_id = ANY($%d)
			)`, argCount)
		args = append(args, pq.Array(req.CategoryIds))
		argCount++
	}

	// authors filter (ANY match)
	if len(req.AuthorIds) > 0 {
		query += fmt.Sprintf(`
			AND EXISTS (
				SELECT 1 FROM book_authors ba
				WHERE ba.book_id = books.id
				  AND ba.author_id = ANY($%d)
			)`, argCount)
		args = append(args, pq.Array(req.AuthorIds))
		argCount++
	}

	if req.PublisherId != "" {
		query += fmt.Sprintf(" AND publisher_id=$%d", argCount)
		args = append(args, req.PublisherId)
		argCount++
	}
	if req.Language != "" {
		query += fmt.Sprintf(" AND language ILIKE $%d", argCount)
		args = append(args, "%"+req.Language+"%")
		argCount++
	}
	if req.IsReferenceOnly {
		query += fmt.Sprintf(" AND is_reference_only=$%d", argCount)
		args = append(args, true)
		argCount++
	}
	if req.Search != "" {
		query += fmt.Sprintf(" AND (title ILIKE $%d OR description ILIKE $%d)", argCount, argCount+1)
		args = append(args, "%"+req.Search+"%", "%"+req.Search+"%")
		argCount += 2
	}

	// pagination
	query += fmt.Sprintf(" LIMIT $%d OFFSET $%d", argCount, argCount+1)
	args = append(args, req.Limit, req.Offset)

	rows, err := r.db.QueryContext(ctx, query, args...)
	if err != nil {
		return nil, err
	}
	defer rows.Close()

	var books []*pb.BookGetRes
	for rows.Next() {
		var b pb.BookGetRes
		if err := rows.Scan(
			&b.Id, &b.Title, &b.CoverImageUrl, &b.FileUrl, &b.Location, &b.IsReferenceOnly,
			&b.Description, &b.Isbn, &b.PublishedDate, &b.PublisherId, &b.Language,
			&b.PageCount, &b.TotalCopies, &b.AvailableCopies,
		); err != nil {
			return nil, err
		}

		// load categories
		cRows, err := r.db.QueryContext(ctx, `SELECT category_id FROM book_categories WHERE book_id=$1`, b.Id)
		if err != nil {
			return nil, err
		}
		for cRows.Next() {
			var cid string
			if err := cRows.Scan(&cid); err != nil {
				cRows.Close()
				return nil, err
			}
			b.CategoryIds = append(b.CategoryIds, cid)
		}
		cRows.Close()

		// load authors
		aRows, err := r.db.QueryContext(ctx, `SELECT author_id FROM book_authors WHERE book_id=$1`, b.Id)
		if err != nil {
			return nil, err
		}
		for aRows.Next() {
			var aid string
			if err := aRows.Scan(&aid); err != nil {
				aRows.Close()
				return nil, err
			}
			b.AuthorIds = append(b.AuthorIds, aid)
		}
		aRows.Close()

		books = append(books, &b)
	}
	if err = rows.Err(); err != nil {
		return nil, err
	}

	// count query (mirror filters)
	countQuery := `SELECT count(id) FROM books WHERE 1=1`
	var countArgs []interface{}
	argCount = 1
	if req.Location != "" {
		countQuery += fmt.Sprintf(" AND location ILIKE $%d", argCount)
		countArgs = append(countArgs, "%"+req.Location+"%")
		argCount++
	}
	if len(req.CategoryIds) > 0 {
		countQuery += fmt.Sprintf(`
			AND EXISTS (
				SELECT 1 FROM book_categories bc
				WHERE bc.book_id = books.id
				  AND bc.category_id = ANY($%d)
			)`, argCount)
		countArgs = append(countArgs, pq.Array(req.CategoryIds))
		argCount++
	}
	if len(req.AuthorIds) > 0 {
		countQuery += fmt.Sprintf(`
			AND EXISTS (
				SELECT 1 FROM book_authors ba
				WHERE ba.book_id = books.id
				  AND ba.author_id = ANY($%d)
			)`, argCount)
		countArgs = append(countArgs, pq.Array(req.AuthorIds))
		argCount++
	}
	if req.PublisherId != "" {
		countQuery += fmt.Sprintf(" AND publisher_id=$%d", argCount)
		countArgs = append(countArgs, req.PublisherId)
		argCount++
	}
	if req.Language != "" {
		countQuery += fmt.Sprintf(" AND language ILIKE $%d", argCount)
		countArgs = append(countArgs, "%"+req.Language+"%")
		argCount++
	}
	if req.IsReferenceOnly {
		countQuery += fmt.Sprintf(" AND is_reference_only=$%d", argCount)
		countArgs = append(countArgs, true)
		argCount++
	}
	if req.Search != "" {
		countQuery += fmt.Sprintf(" AND (title ILIKE $%d OR description ILIKE $%d)", argCount, argCount+1)
		countArgs = append(countArgs, "%"+req.Search+"%", "%"+req.Search+"%")
		argCount += 2
	}

	var total int64
	if err := r.db.QueryRowContext(ctx, countQuery, countArgs...).Scan(&total); err != nil {
		return nil, err
	}

	return &pb.BooksGetAllRes{
		Books:      books,
		TotalCount: total,
	}, nil
}
```

