Since your protobuf schema now expects **objects** (`CategoryGetRes`, `AuthorGetRes`, `PublisherGetRes`) instead of just IDs, you need to **join or separately query** those tables and build the nested objects in Go before returning.  

Here’s how you can adjust your repo code:

```go
func (r *BookRepo) GetBook(ctx context.Context, req *pb.ByID) (*pb.BookGetRes, error) {
	query := `
		SELECT id, title, cover_image_url, file_url, location, is_reference_only, description,
		       isbn, published_date, publisher_id, language, page_count, total_copies, available_copies
		FROM books WHERE id = $1
	`
	var b pb.BookGetRes
	var publisherID string
	err := r.db.QueryRowContext(ctx, query, req.Id).Scan(
		&b.Id, &b.Title, &b.CoverImageUrl, &b.FileUrl, &b.Location, &b.IsReferenceOnly,
		&b.Description, &b.Isbn, &b.PublishedDate, &publisherID, &b.Language,
		&b.PageCount, &b.TotalCopies, &b.AvailableCopies,
	)
	if err != nil {
		return nil, err
	}

	// load publisher
	if publisherID != "" {
		var pub pb.PublisherGetRes
		err := r.db.QueryRowContext(ctx, `SELECT id, name FROM publishers WHERE id=$1`, publisherID).Scan(
			&pub.Id, &pub.Name,
		)
		if err != nil {
			return nil, err
		}
		b.PublisherId = &pub
	}

	// load categories
	cRows, err := r.db.QueryContext(ctx, `
		SELECT c.id, c.name
		FROM categories c
		JOIN book_categories bc ON bc.category_id = c.id
		WHERE bc.book_id = $1
	`, b.Id)
	if err != nil {
		return nil, err
	}
	for cRows.Next() {
		var c pb.CategoryGetRes
		if err := cRows.Scan(&c.Id, &c.Name); err != nil {
			cRows.Close()
			return nil, err
		}
		b.CategoryIds = append(b.CategoryIds, &c)
	}
	cRows.Close()

	// load authors
	aRows, err := r.db.QueryContext(ctx, `
		SELECT a.id, a.name
		FROM authors a
		JOIN book_authors ba ON ba.author_id = a.id
		WHERE ba.book_id = $1
	`, b.Id)
	if err != nil {
		return nil, err
	}
	for aRows.Next() {
		var a pb.AuthorGetRes
		if err := aRows.Scan(&a.Id, &a.Name); err != nil {
			aRows.Close()
			return nil, err
		}
		b.AuthorIds = append(b.AuthorIds, &a)
	}
	aRows.Close()

	return &b, nil
}
