		var publisherID string
		if err := rows.Scan(
			&b.Id, &b.Title, &b.CoverImageUrl, &b.FileUrl, &b.Location, &b.IsReferenceOnly,
			&b.Description, &b.Isbn, &b.PublishedDate, &publisherID, &b.Language,
			&b.PageCount, &b.TotalCopies, &b.AvailableCopies,
		); err != nil {
			return nil, err
