		// load publisher object
		if publisherID != "" {
			var pub pb.PublisherGetRes
			err := r.db.QueryRowContext(ctx, `SELECT id, name FROM publishers WHERE id=$1`, publisherID).
				Scan(&pub.Id, &pub.Name)
			if err != nil {
