			}
			b.PublisherId = &pub
		}

		// load categories as objects
		cRows, err := r.db.QueryContext(ctx, `
			SELECT c.id, c.name
			FROM categories c
			JOIN book_categories bc ON bc.category_id = c.id
			WHERE bc.book_id=$1
		`, b.Id)
